from collections import defaultdict

class Solution:
    def brightestPosition(self, lights: list[list[int]]) -> int:
        diff = defaultdict(int)
        for p, r in lights:
            diff[p - r] += 1
            diff[p + r + 1] -= 1
        best_pos = None
        max_bright = -1
        curr = 0
        for pos in sorted(diff.keys()):
            curr += diff[pos]
            if curr > max_bright:
                max_bright = curr
                best_pos = pos
        return best_pos

class Solution {
public:
    int brightestPosition(vector<vector<int>>& lights) {
        map<int, int> diff;
        for (const auto& l : lights) {
            diff[l[0] - l[1]]++;
            diff[l[0] + l[1] + 1]--;
        }
        int best_pos = 0;
        int max_bright = -1;
        int curr = 0;
        for (const auto& [pos, delta] : diff) {
            curr += delta;
            if (curr > max_bright) {
                max_bright = curr;
                best_pos = pos;
            }
        }
        return best_pos;
    }
};

class Solution {
    public int brightestPosition(int[][] lights) {
        TreeMap<Integer, Integer> diff = new TreeMap<>();
        for (int[] l : lights) {
            diff.put(l[0] - l[1], diff.getOrDefault(l[0] - l[1], 0) + 1);
            diff.put(l[0] + l[1] + 1, diff.getOrDefault(l[0] + l[1] + 1, 0) - 1);
        }
        int bestPos = 0;
        int maxBright = -1;
        int curr = 0;
        for (Map.Entry<Integer, Integer> entry : diff.entrySet()) {
            curr += entry.getValue();
            if (curr > maxBright) {
                maxBright = curr;
                bestPos = entry.getKey();
            }
        }
        return bestPos;
    }
}

var brightestPosition = function(lights) {
  const diff = new Map();
  for (const [p, r] of lights) {
    diff.set(p - r, (diff.get(p - r) || 0) + 1);
    diff.set(p + r + 1, (diff.get(p + r + 1) || 0) - 1);
  }
  const pts = Array.from(diff.keys()).sort((a, b) => a - b);
  let bestPos = 0;
  let maxBright = -1;
  let curr = 0;
  for (const pos of pts) {
    curr += diff.get(pos);
    if (curr > maxBright) {
      maxBright = curr;
      bestPos = pos;
    }
  }
  return bestPos;
};
